<div class="drawer-backdrop" x-cloak x-show="bag" @click.self="bag=false">
    <aside class="cart-drawer" role="dialog" aria-modal="true" aria-labelledby="bag-title" @keydown.tab="window.trapDialogFocus($event,$el)" :aria-busy="$store.cart.busy">
        <div class="drawer-heading"><div><span class="eyebrow">YOUR EVERYDAY EDIT</span><h2 id="bag-title">Shopping bag <span x-text="'('+$store.cart.count+')'"></span></h2></div><button x-ref="closeBag" class="icon-button" @click="bag=false" aria-label="Close shopping bag">×</button></div>
        <p class="drawer-error" x-show="$store.cart.error" x-text="$store.cart.error" role="alert"></p>
        <div class="drawer-lines"><template x-for="item in $store.cart.items" :key="item.id"><article class="drawer-item"><a :href="item.url"><img :src="item.image" :alt="item.name" width="88" height="110"></a><div><h3><a :href="item.url" x-text="item.name"></a></h3><p><span x-text="item.size"></span> / <span x-text="item.color"></span></p><small x-text="item.unit_price_label+' each'"></small><div class="drawer-item-controls"><div class="stepper"><button @click="$store.cart.change(item,item.quantity-1)" :disabled="$store.cart.busy" :aria-label="'Decrease quantity of '+item.name">−</button><span x-text="item.quantity" aria-live="polite"></span><button @click="$store.cart.change(item,item.quantity+1)" :disabled="$store.cart.busy||item.quantity>=item.max" :aria-label="'Increase quantity of '+item.name">+</button></div><button class="remove-button" @click="$store.cart.change(item,0)" :disabled="$store.cart.busy" :aria-label="'Remove '+item.name">Remove</button></div><p class="field-error" x-show="!item.available">Currently unavailable. Remove this item to continue.</p></div><strong x-text="item.total_label"></strong></article></template>
        <div class="empty" x-show="!$store.cart.items.length"><i data-lucide="shopping-bag"></i><h3>A little room for something good.</h3><p>Find the pieces you’ll reach for every day.</p><a class="button" href="/shop">Explore the collection ↗</a></div></div>
        <div class="drawer-footer" x-show="$store.cart.items.length"><div class="summary-row total"><span>Subtotal</span><strong x-text="$store.cart.subtotal_label"></strong></div><p>Delivery and coupon discounts are calculated at checkout.</p><a href="/checkout" class="button full">Continue to checkout <span>↗</span></a><a href="/cart" class="button button-light full">View shopping bag</a><span class="small"><i data-lucide="banknote"></i> Guest checkout · Cash on Delivery</span></div>
    </aside>
</div>
